import{_ as o,o as t,c as a,a2 as s}from"./chunks/framework.CyZTVJbV.js";const p=JSON.parse('{"title":"kiwa v1.16 released — Storybook 8 + Playwright CT + Chromatic (Component test 縦軸)","description":"","frontmatter":{},"headers":[],"relativePath":"announcements/v1.16/gh-discussions-announcement.md","filePath":"announcements/v1.16/gh-discussions-announcement.md"}'),r={name:"announcements/v1.16/gh-discussions-announcement.md"};function i(n,e,c,d,l,m){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="kiwa-v1-16-released-—-storybook-8-playwright-ct-chromatic-component-test-縦軸" tabindex="-1">kiwa v1.16 released — Storybook 8 + Playwright CT + Chromatic (Component test 縦軸) <a class="header-anchor" href="#kiwa-v1-16-released-—-storybook-8-playwright-ct-chromatic-component-test-縦軸" aria-label="Permalink to &quot;kiwa v1.16 released — Storybook 8 + Playwright CT + Chromatic (Component test 縦軸)&quot;">​</a></h1><p>v1.16 is out. After v1.15&#39;s AI-LLM depth (<code>@kiwa-lab/ai-llm</code> v0.2 multimodal + <code>@kiwa-lab/mcp</code> v0.1 + <code>@kiwa-lab/agent</code> v0.1), v1.16 turns to the <strong>frontend component layer</strong> that nearly every 2026 SaaS team ships: Storybook 8, Playwright Component Testing, and Chromatic — three integrations, one unified mock harness.</p><h2 id="what-shipped" tabindex="-1">What shipped <a class="header-anchor" href="#what-shipped" aria-label="Permalink to &quot;What shipped&quot;">​</a></h2><ul><li><strong><code>@kiwa-lab/component</code> v0.1</strong> — three integrations under one API. <code>createStoryRegistry</code> implements Storybook 8 CSF3 (args deep merge + play function runner + <code>parameters.a11y</code> / <code>parameters.chromatic</code> passthrough + heuristic a11y checker for button-name / image-alt / label). <code>createPlaywrightCTMock</code> provides a Locator API subset (<code>mount + getByText + getByRole + click + fill + textContent + count</code>) without booting a real browser. <code>createChromaticVisualMock</code> implements a SHA-256 markup hash-based baseline / diff / accept-reject workflow with multi viewport and <code>parameters.chromatic.diffThreshold</code> support. Everything is framework agnostic: React / Vue / Svelte / Solid all reduce to <code>ComponentRender = (args) =&gt; MockNode</code>. 80 tests pass across <code>storybook.test.ts</code> (16) + <code>playwright-ct.test.ts</code> (13) + <code>chromatic.test.ts</code> (14) + <code>fixture.test.ts</code> (18) + <code>dom.test.ts</code> (19).</li><li><strong><code>examples/dogfood-storybook-design-system</code></strong> — 12 React design-system primitives (Button / Input / Card / Modal / Dropdown / Tabs / Toast / Table / Tooltip / Badge / Avatar / Icon), 30+ CSF3 stories, 53 tests + 3-layer perf gate PASS. A 6-op adapter contract (<code>registerAll</code> / <code>listStories</code> / <code>resolveArgs</code> / <code>mount</code> / <code>play</code> / <code>runA11y</code>) drives mock vs real behavioural fidelity into the 7-axis release gate (AI-LLM 4 axes not overlaid for component providers). Play functions dispatch via <code>fireEvent(node, {type, target})</code> and mock adapter instruments handler invocations to keep <code>metric.handlersInvoked</code> from double-counting registrations.</li><li><strong><code>examples/dogfood-form-ct</code></strong> — 5 form patterns (login / signup / checkout / profile / search) × 4 axes (mount / validation error / submit success / a11y violation 0) = 20 ops per adapter. 49 behavior tests + 4 flow perf ops PASS. <code>FormCTAdapter</code> unifies mock (in-memory MockNode canvas) and real (<code>PW_CT_ENDPOINT</code> env-skip) implementations; fidelity report emits to <code>quality-report/fidelity-latest.{json,md}</code> per canonical path.</li><li><strong><code>examples/dogfood-visual-regression</code></strong> — 10 UI scenes (5 primitives <code>card</code> / <code>modal</code> / <code>table</code> / <code>toast</code> / <code>form</code> × 2 themes light + dark). <code>VisualRegressionAdapter</code> covers <code>seedBaselines</code> / <code>captureOne</code> / <code>captureAll</code> / <code>review</code>. Diff-on-intent-change flips 1 visible bit (button label / heading rename / cell text) → FAIL; <code>review(&#39;accept&#39;)</code> restores baseline → PASS. 57 tests + 3-layer perf 4 ops PASS, coverage 92/88/95, mutation 73.33%. 7-axis release gate verdict PASS.</li><li><strong>docs</strong> — 3 new tutorials (19 Storybook 8 design system / 20 Playwright CT × 5 forms / 21 Chromatic 4-state machine) + additive migration guide v1.15 → v1.16 + concept doc <code>component-testing.md</code> documenting <strong>3 surfaces × 6 semantic axes</strong> (story registration / args resolution / interaction trace / a11y / snapshot hash / review workflow) as the SSOT. VitePress sidebar refreshed; gh-pages published.</li></ul><h2 id="numbers" tabindex="-1">Numbers <a class="header-anchor" href="#numbers" aria-label="Permalink to &quot;Numbers&quot;">​</a></h2><ul><li><strong>6 sub-Issues resolved</strong> (#763-#768)</li><li><strong>6 PRs merged</strong> (#769-#773 + this publish PR)</li><li><strong>1 new package</strong> (<code>@kiwa-lab/component</code> v0.1.0)</li><li><strong>3 new dogfood apps</strong> with fidelity reports feeding the 7-axis release gate</li><li><strong>80 unit tests</strong> in the harness + <strong>159 dogfood tests</strong> (53 + 49 + 57) all pass</li></ul><h2 id="_6-milestone-streak" tabindex="-1">6-milestone streak <a class="header-anchor" href="#_6-milestone-streak" aria-label="Permalink to &quot;6-milestone streak&quot;">​</a></h2><p>v1.11 (release gate) → v1.12 (non-determinism) → v1.13 (time-axis) → v1.14 (horizontal expansion) → v1.15 (AI-LLM depth) → <strong>v1.16 (component depth)</strong>. Every milestone since v1.11 has landed 6 sub-Issues in full.</p><h2 id="v2-0-candidates" tabindex="-1">v2.0 candidates <a class="header-anchor" href="#v2-0-candidates" aria-label="Permalink to &quot;v2.0 candidates&quot;">​</a></h2><ul><li>Multi-version Vitest matrix (Vitest 1.x vs 2.x vs 3.x parity)</li><li>Desktop (Electron / Tauri) + mobile (React Native / Expo) adapters</li><li>Framework depth (SolidJS / Fresh / HonoJS)</li><li>Coverage 100% milestone</li><li>Observability v2 (dashboard + alert + trace flame graph + log correlation)</li><li>Blockchain depth (Reth Rust Ethereum execution client + Foundry-rs 深化 + dApp e2e 拡張)</li></ul><p>Feedback welcome on which of these should land next.</p>',11)])])}const g=o(r,[["render",i]]);export{p as __pageData,g as default};
